import test from 'node:test';
import assert from 'node:assert/strict';
import {spawn} from 'node:child_process';
import {mkdtemp,writeFile,rm} from 'node:fs/promises';
import {tmpdir} from 'node:os';
import {fileURLToPath} from 'node:url';
import {testServer} from '../../server/test/helpers.js';
async function scenario(fn){
  const server=await testServer();const dir=await mkdtemp(tmpdir()+'/crew-issue-cli-');
  try{
    const api=server.agent();const auth=await api('POST','/auth/signup',{name:'CLI Owner',email:'cli@example.test',password:'correct-horse-battery'});
    const org=(await api('POST','/orgs',{name:'CLI org'})).data.organization;
    const project=(await api('POST','/orgs/'+org.id+'/projects',{key:'CLI',name:'CLI project'})).data.project;
    await writeFile(dir+'/config.json',JSON.stringify({url:server.url,cookie:auth.cookie}));
    const cli=args=>new Promise((resolve,reject)=>{
      const child=spawn(process.execPath,[fileURLToPath(new URL('../bin/crew.js',import.meta.url)),...args,'--config',dir+'/config.json','--json']);let stdout='',stderr='';
      const timer=setTimeout(()=>{child.kill('SIGKILL');reject(new Error('CLI deadline exceeded'));},10000);
      child.stdout.on('data',data=>stdout+=data);child.stderr.on('data',data=>stderr+=data);child.on('error',reject);child.on('close',code=>{clearTimeout(timer);resolve({code,stdout,stderr,data:stdout.trim()?JSON.parse(stdout):null});});
    });
    await fn({cli,api,project});
  }finally{await server.close();await rm(dir,{recursive:true,force:true});}
}
test('actual issue CLI creates edits and reads every supplied field',()=>scenario(async({cli,project})=>{
  const created=await cli(['issue','create',project.id,'--title','CLI issue','--description','Markdown **text**','--priority','2','--estimate','3.5','--due','2028-02-29']);
  assert.equal(created.code,0,created.stderr);const id=created.data.issue.id;assert.equal(created.data.issue.key,'CLI-1');assert.equal(created.data.issue.estimate,3.5);
  const edited=await cli(['issue','edit',id,'--title','Edited','--estimate','none']);assert.equal(edited.code,0,edited.stderr);assert.equal(edited.data.issue.estimate,null);
  const shown=await cli(['issue','show',id]);assert.equal(shown.data.issue.title,'Edited');assert.equal(shown.data.issue.description,'Markdown **text**');
}));
test('actual issue CLI filters paginates and manages labels',()=>scenario(async({cli,project})=>{
  const label=await cli(['issue','label-create',project.id,'--name','Release','--color','#123456']);assert.equal(label.code,0,label.stderr);
  await cli(['issue','create',project.id,'--title','Ship','--labels',label.data.label.id]);
  const list=await cli(['issue','list',project.id,'--label',label.data.label.id,'--limit','1']);assert.equal(list.code,0,list.stderr);assert.equal(list.data.items[0].title,'Ship');
  const changed=await cli(['issue','label-edit',label.data.label.id,'--name','Milestone']);assert.equal(changed.code,0,changed.stderr);
  const labels=await cli(['issue','labels',project.id]);assert.equal(labels.data.items[0].name,'Milestone');
}));
test('actual issue CLI rejects invalid edits and requires explicit deletion',()=>scenario(async({cli,project})=>{
  const created=await cli(['issue','create',project.id,'--title','Keep']);const id=created.data.issue.id;
  assert.equal((await cli(['issue','edit',id,'--priority','9'])).code,1);
  assert.equal((await cli(['issue','delete',id])).code,1);
  assert.equal((await cli(['issue','show',id])).code,0);
  assert.equal((await cli(['issue','delete',id,'--yes'])).code,0);
  assert.equal((await cli(['issue','show',id])).code,1);
}));

test('actual issue CLI comments previews mentions and all relation actions persist',()=>scenario(async({cli,project})=>{
  const first=(await cli(['issue','create',project.id,'--title','Discuss'])).data.issue;
  const second=(await cli(['issue','create',project.id,'--title','Related'])).data.issue;
  const comment=await cli(['issue','comment',first.id,'--body','**Ship** <script>bad</script>']);assert.equal(comment.code,0,comment.stderr);assert.ok(comment.data.comment.html.includes('&lt;script&gt;'));
  assert.equal((await cli(['issue','comment-edit',comment.data.comment.id,'--body','Edited comment'])).code,0);
  assert.equal((await cli(['issue','comments',first.id])).data.items[0].body,'Edited comment');
  for(const kind of ['blocks','duplicates','relates']){
    const relation=await cli(['issue','relate',first.id,'--target',second.id,'--kind',kind]);assert.equal(relation.code,0,relation.stderr);
    assert.equal((await cli(['issue','relations',first.id])).data.items.some(item=>item.kind===kind),true);
    assert.equal((await cli(['issue','unrelate',relation.data.relation.id,'--yes'])).code,0);
  }
  assert.equal((await cli(['issue','comment-delete',comment.data.comment.id,'--yes'])).code,0);assert.deepEqual((await cli(['issue','comments',first.id])).data.items,[]);
}));

import {visibleMentionedUserIds} from './mentions.js';
import {AppError,validation} from '@crew/shared';
import {commentInput} from '../../../../shared/src/schemas/discussion.js';
import {analyzeMarkdown} from '../../../../shared/src/markdown.js';
import {getIssue,validateIssueReferences} from './issues.js';
export const mentionedUsers=visibleMentionedUserIds;
export function publicComment(ctx,row) {
  const issue=getIssue(ctx,row.issue_id);
  const author=ctx.db.prepare('SELECT id,name FROM users WHERE id=?').get(row.author_id);
  return {id:row.id,issueId:row.issue_id,projectId:issue.projectId,orgId:issue.orgId,
    authorId:row.author_id,author:{id:author.id,name:author.name},body:row.body,
    html:analyzeMarkdown(row.body).html,mentionedUserIds:mentionedUsers(ctx,issue,row.body),
    createdAt:row.created_at,updatedAt:row.updated_at};
}
export function commentRow(ctx,id) {
  const row=ctx.db.prepare('SELECT * FROM comments WHERE id=?').get(id);
  if(!row)throw new AppError('NOT_FOUND','Comment not found',404);
  return row;
}
export function getComment(ctx,id){return publicComment(ctx,commentRow(ctx,id));}
export function listComments(ctx,issueId) {
  return ctx.db.prepare('SELECT * FROM comments WHERE issue_id=? ORDER BY created_at,id').all(issueId).map(row=>publicComment(ctx,row));
}
function emit(ctx,req,action,before,after,issue) {
  const comment=after??before;
  ctx.bus.emit({actorId:req.user.id,orgId:issue.orgId,projectId:issue.projectId,
    entityType:'comment',entityId:comment.id,action,before:before??null,
    after:after?{...after,issue,mentionedUserIds:after.mentionedUserIds,userIds:after.mentionedUserIds}:null,
    issueId:issue.id,mentionedUserIds:after?.mentionedUserIds??[],time:ctx.now()});
}
export function createComment(ctx,req,issueId,body) {
  const issue=getIssue(ctx,issueId),input=commentInput(body);
  validateIssueReferences(ctx,issue.projectId,{});
  if(!input.body.trim())throw validation({body:'Write a comment before posting'});
  const id=ctx.id(),time=ctx.now();
  ctx.db.prepare('INSERT INTO comments VALUES (?,?,?,?,?,?)').run(id,issueId,req.user.id,input.body,time,time);
  const comment=getComment(ctx,id);emit(ctx,req,'created',null,comment,issue);return comment;
}
export function updateComment(ctx,req,id,body) {
  const before=getComment(ctx,id),issue=getIssue(ctx,before.issueId),input=commentInput(body);
  validateIssueReferences(ctx,issue.projectId,{});
  if(!input.body.trim())throw validation({body:'Write a comment before saving'});
  ctx.db.prepare('UPDATE comments SET body=?,updated_at=? WHERE id=?').run(input.body,ctx.now(),id);
  const after=getComment(ctx,id);emit(ctx,req,'updated',before,after,issue);return after;
}
export function deleteComment(ctx,req,id) {
  const before=getComment(ctx,id),issue=getIssue(ctx,before.issueId);
  validateIssueReferences(ctx,issue.projectId,{});
  ctx.db.prepare('DELETE FROM comments WHERE id=?').run(id);
  emit(ctx,req,'deleted',before,null,issue);return before;
}
export function registerComments(ctx) {
  const {app,requireAuth,permissions:p}=ctx;
  function permitted(req,permission='project:read') {
    const issue=getIssue(ctx,req.params.issueId);p.assertProject(req,issue.projectId,permission);return issue;
  }
  function editable(req) {
    const comment=getComment(ctx,req.params.commentId);
    p.assertProject(req,comment.projectId,'comment:write');
    if(comment.authorId!==req.user.id&&!p.canOrg(req.user.id,comment.orgId,'org:manage'))throw new AppError('FORBIDDEN','Only the author or organization administrator may change this comment',403);
    return comment;
  }
  app.get('/api/v1/issues/:issueId/comments',requireAuth,(req,res)=>{
    permitted(req);res.json(ctx.paginate(listComments(ctx,req.params.issueId),req.query));
  });
  app.post('/api/v1/issues/:issueId/comments',requireAuth,(req,res)=>{
    permitted(req,'comment:write');res.status(201).json({comment:createComment(ctx,req,req.params.issueId,req.body)});
  });
  app.patch('/api/v1/comments/:commentId',requireAuth,(req,res)=>{editable(req);res.json({comment:updateComment(ctx,req,req.params.commentId,req.body)});});
  app.delete('/api/v1/comments/:commentId',requireAuth,(req,res)=>{editable(req);deleteComment(ctx,req,req.params.commentId);res.json({ok:true});});
}

import {visibleMentionedUserIds} from './mentions.js';
import {integer} from '@crew/shared';
import {AppError,validation} from '@crew/shared';
import {issueInput,issueMatches,issueKey} from '../../../../shared/src/schemas/issue.js';
export const publicLabel=row=>({id:row.id,projectId:row.project_id,name:row.name,color:row.color,createdAt:row.created_at,updatedAt:row.updated_at});
export function publicIssue(row) {
  return {
    id:row.id,orgId:row.org_id,projectId:row.project_id,projectKey:row.project_key,
    number:row.number,key:issueKey(row.project_key,row.number),title:row.title,
    description:row.description,statusId:row.status_id,statusName:row.status_name,
    statusCategory:row.status_category,priority:row.priority,assigneeId:row.assignee_id,
    assignee:row.assignee_id?{id:row.assignee_id,name:row.assignee_name,email:row.assignee_email}:null,
    estimate:row.estimate,dueDate:row.due_date,parentId:row.parent_id,createdBy:row.created_by,
    creator:{id:row.created_by,name:row.creator_name},rank:row.rank,
    createdAt:row.created_at,updatedAt:row.updated_at
  };
}
const issueSelect=`SELECT i.*,p.org_id,p.key AS project_key,s.name AS status_name,
  s.category AS status_category,u.name AS assignee_name,u.email AS assignee_email,
  creator.name AS creator_name FROM issues i
  JOIN projects p ON p.id=i.project_id JOIN project_statuses s ON s.id=i.status_id
  LEFT JOIN users u ON u.id=i.assignee_id JOIN users creator ON creator.id=i.created_by`;
export function issueRow(ctx,id) {
  const row=ctx.db.prepare(issueSelect+' WHERE i.id=?').get(id);
  if(!row)throw new AppError('NOT_FOUND','Issue not found',404);
  return row;
}
export function getIssue(ctx,id) {
  const issue=publicIssue(issueRow(ctx,id));
  issue.labels=ctx.db.prepare('SELECT l.* FROM labels l JOIN issue_labels il ON il.label_id=l.id WHERE il.issue_id=? ORDER BY l.name,l.id').all(id).map(publicLabel);
  issue.mentionedUserIds=visibleMentionedUserIds(ctx,issue,issue.description);
  return issue;
}
export function listIssues(ctx,projectId,query={}) {
  if(query.priority!==undefined)integer(query.priority,'priority',{min:0,max:4});
  const rows=ctx.db.prepare(issueSelect+' WHERE i.project_id=? ORDER BY i.number DESC,i.id').all(projectId);
  return rows.map(row=>getIssue(ctx,row.id)).filter(issue=>issueMatches(issue,query));
}
export function emitIssue(ctx,req,action,before,after) {
  const item=after??before;
  return ctx.bus.emit({actorId:req.user.id,orgId:item.orgId,projectId:item.projectId,
    entityType:'issue',entityId:item.id,action,before:before??null,after:after??null,time:ctx.now()});
}
export function validateIssueReferences(ctx,projectId,input,issueId=null) {
  const {db}=ctx;
  const project=db.prepare('SELECT * FROM projects WHERE id=?').get(projectId);
  if(!project)throw new AppError('NOT_FOUND','Project not found',404);
  if(project.archived)throw new AppError('CONFLICT','Archived projects are read-only',409);
  if(input.statusId!==undefined&&!db.prepare('SELECT 1 FROM project_statuses WHERE id=? AND project_id=?').get(input.statusId,projectId))throw validation({statusId:'Choose a status in this project'});
  if(input.assigneeId&&!ctx.permissions.canProject(input.assigneeId,projectId,'project:read'))throw validation({assigneeId:'Assignee must have access to this project'});
  if(input.parentId){
    const parent=db.prepare('SELECT id,project_id,parent_id FROM issues WHERE id=?').get(input.parentId);
    if(!parent||parent.project_id!==projectId)throw validation({parentId:'Parent must belong to this project'});
    const visited=new Set();
    let current=parent;
    while(current){
      if(current.id===issueId||visited.has(current.id))throw validation({parentId:'An issue cannot be its own ancestor'});
      visited.add(current.id);
      current=current.parent_id?db.prepare('SELECT id,parent_id FROM issues WHERE id=?').get(current.parent_id):null;
    }
  }
  if(input.labelIds)for(const labelId of input.labelIds){
    if(!db.prepare('SELECT 1 FROM labels WHERE id=? AND project_id=?').get(labelId,projectId))throw validation({labelIds:'All labels must belong to this project'});
  }
  return project;
}
export function replaceIssueLabels(ctx,issueId,labelIds) {
  ctx.db.prepare('DELETE FROM issue_labels WHERE issue_id=?').run(issueId);
  const insert=ctx.db.prepare('INSERT INTO issue_labels VALUES (?,?)');
  for(const labelId of labelIds)insert.run(issueId,labelId);
}
export function createIssue(ctx,req,projectId,body) {
  const input=issueInput(body);
  const id=ctx.id(),time=ctx.now();
  const issue=ctx.transaction(()=>{
    const project=validateIssueReferences(ctx,projectId,input);
    const statusId=input.statusId??ctx.db.prepare('SELECT id FROM project_statuses WHERE project_id=? ORDER BY position,id LIMIT 1').get(projectId)?.id;
    if(!statusId)throw validation({statusId:'Configure a project workflow before creating issues'});
    const number=project.next_issue_number;
    ctx.db.prepare('UPDATE projects SET next_issue_number=next_issue_number+1 WHERE id=?').run(projectId);
    const rank=ctx.db.prepare('SELECT COALESCE(MAX(rank),0)+1024 AS rank FROM issues WHERE project_id=? AND status_id=?').get(projectId,statusId).rank;
    ctx.db.prepare(`INSERT INTO issues
      (id,project_id,number,title,description,status_id,priority,assignee_id,estimate,due_date,parent_id,created_by,rank,created_at,updated_at)
      VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).run(id,projectId,number,input.title,input.description,statusId,input.priority,input.assigneeId,input.estimate,input.dueDate,input.parentId,req.user.id,rank,time,time);
    replaceIssueLabels(ctx,id,input.labelIds);
    return getIssue(ctx,id);
  });
  emitIssue(ctx,req,'created',null,issue);
  return issue;
}
export function updateIssue(ctx,req,id,body) {
  const before=getIssue(ctx,id),input=issueInput(body,{partial:true});
  const after=ctx.transaction(()=>{
    validateIssueReferences(ctx,before.projectId,input,id);
    if(input.statusId&&input.statusId!==before.statusId){
      const rank=ctx.db.prepare('SELECT COALESCE(MAX(rank),0)+1024 AS rank FROM issues WHERE project_id=? AND status_id=?').get(before.projectId,input.statusId).rank;
      ctx.db.prepare('UPDATE issues SET rank=? WHERE id=?').run(rank,id);
    }
    const mapping={title:'title',description:'description',statusId:'status_id',priority:'priority',assigneeId:'assignee_id',estimate:'estimate',dueDate:'due_date',parentId:'parent_id'};
    const entries=Object.entries(input).filter(([key])=>key!=='labelIds');
    if(entries.length)ctx.db.prepare(`UPDATE issues SET ${entries.map(([key])=>mapping[key]+'=?').join(',')},updated_at=? WHERE id=?`).run(...entries.map(([,value])=>value),ctx.now(),id);
    else ctx.db.prepare('UPDATE issues SET updated_at=? WHERE id=?').run(ctx.now(),id);
    if(input.labelIds)replaceIssueLabels(ctx,id,input.labelIds);
    return getIssue(ctx,id);
  });
  emitIssue(ctx,req,'updated',before,after);
  return after;
}
export function deleteIssue(ctx,req,id) {
  const before=getIssue(ctx,id);
  validateIssueReferences(ctx,before.projectId,{});
  const children=ctx.db.prepare('SELECT id FROM issues WHERE parent_id=?').all(id).map(row=>getIssue(ctx,row.id));
  ctx.transaction(()=>{
    ctx.db.prepare('UPDATE issues SET updated_at=? WHERE parent_id=?').run(ctx.now(),id);
    ctx.db.prepare('DELETE FROM issues WHERE id=?').run(id);
  });
  for(const child of children)emitIssue(ctx,req,'updated',child,getIssue(ctx,child.id));
  emitIssue(ctx,req,'deleted',before,null);
  return before;
}

import {extractMentions} from '../../../../shared/src/markdown.js';
export function visibleMentionedUserIds(ctx,issue,body) {
  const handles=new Set(extractMentions(body));
  if(!handles.size)return [];
  const members=ctx.db.prepare('SELECT u.id,u.name,u.email FROM users u JOIN memberships m ON m.user_id=u.id WHERE m.org_id=?').all(issue.orgId);
  return members.filter(user=>[user.id,user.name,user.email,user.email.split('@')[0]].some(value=>handles.has(value.toLowerCase()))&&ctx.permissions.canProject(user.id,issue.projectId,'project:read')).map(user=>user.id);
}

import test from 'node:test';
import assert from 'node:assert/strict';
import {testServer} from './helpers.js';
async function scenario(fn) {
  const server=await testServer();
  try{
    const request=server.agent();
    const signup=await request('POST','/auth/signup',{name:'Owner',email:'owner@example.test',password:'correct-horse-battery'});
    assert.equal(signup.status,201);
    const user=signup.data.user;
    const {data:{organization}}=await request('POST','/orgs',{name:'Issue team'});
    const created=await request('POST','/orgs/'+organization.id+'/projects',{key:'ISS',name:'Issue project'});
    assert.equal(created.status,201);
    const project=created.data.project;
    const create=async body=>request('POST','/projects/'+project.id+'/issues',body);
    await fn({server,request,user,organization,project,create});
  }finally{await server.close();}
}
test('issues persist every field and hydrate labels status and identities',()=>scenario(async({request,project,user,create})=>{
  const label=(await request('POST','/projects/'+project.id+'/labels',{name:'Backend',color:'#ABCDEF'})).data.label;
  const parent=(await create({title:'Parent'})).data.issue;
  const result=await create({title:'Ship',description:'# Plan\nDetails',statusId:project.statuses[1].id,priority:2,assigneeId:user.id,estimate:2.5,dueDate:'2028-02-29',parentId:parent.id,labelIds:[label.id]});
  assert.equal(result.status,201);const issue=result.data.issue;
  assert.equal(issue.key,'ISS-2');assert.equal(issue.statusCategory,'active');assert.equal(issue.assignee.id,user.id);assert.equal(issue.creator.name,'Owner');
  for(const [key,value] of Object.entries({title:'Ship',description:'# Plan\nDetails',priority:2,estimate:2.5,dueDate:'2028-02-29',parentId:parent.id}))assert.equal(issue[key],value);
  assert.equal(issue.labels[0].name,'Backend');assert.equal(issue.labels[0].color,'#abcdef');
  assert.deepEqual((await request('GET','/issues/'+issue.id)).data.issue,issue);
}));
test('issue numbering is independent per project and never reuses deletion gaps',()=>scenario(async({request,organization,project,create})=>{
  const first=(await create({title:'One'})).data.issue;await request('DELETE','/issues/'+first.id);
  assert.equal((await create({title:'Two'})).data.issue.number,2);
  const other=(await request('POST','/orgs/'+organization.id+'/projects',{key:'NEW',name:'Other'})).data.project;
  assert.equal((await request('POST','/projects/'+other.id+'/issues',{title:'Other one'})).data.issue.key,'NEW-1');
  assert.equal((await request('GET','/projects/'+project.id)).data.project.nextIssueNumber,3);
}));
test('invalid issue creation rolls back numbering and all fields',()=>scenario(async({request,project,create})=>{
  const result=await create({title:'Invalid',statusId:'missing'});assert.equal(result.status,422);assert.ok(result.data.error.details.statusId);
  assert.equal((await create({title:'Valid'})).data.issue.number,1);assert.equal((await request('GET','/projects/'+project.id+'/issues')).data.items.length,1);
}));
test('issue parents cannot cross projects or form ancestry cycles',()=>scenario(async({request,create,organization})=>{
  const parent=(await create({title:'Parent'})).data.issue;
  const child=(await create({title:'Child',parentId:parent.id})).data.issue;
  assert.equal((await request('PATCH','/issues/'+parent.id,{parentId:child.id})).status,422);
  assert.equal((await request('PATCH','/issues/'+parent.id,{parentId:parent.id})).status,422);
  const other=(await request('POST','/orgs/'+organization.id+'/projects',{key:'OTH',name:'Other'})).data.project;
  assert.equal((await request('POST','/projects/'+other.id+'/issues',{title:'Wrong parent',parentId:parent.id})).status,422);
}));
test('status labels and assignee must belong to the accessible project',()=>scenario(async({request,create,organization})=>{
  const other=(await request('POST','/orgs/'+organization.id+'/projects',{key:'OTH',name:'Other'})).data.project;
  const label=(await request('POST','/projects/'+other.id+'/labels',{name:'Other label'})).data.label;
  assert.equal((await create({title:'Wrong status',statusId:other.statuses[0].id})).status,422);
  assert.equal((await create({title:'Wrong label',labelIds:[label.id]})).status,422);
  assert.equal((await create({title:'Wrong assignee',assigneeId:'unknown'})).status,422);
}));
test('editing issue fields preserves omitted fields and clears nullable values',()=>scenario(async({request,create,user})=>{
  const issue=(await create({title:'Original',description:'Keep',estimate:5,dueDate:'2026-12-01',assigneeId:user.id})).data.issue;
  const result=await request('PATCH','/issues/'+issue.id,{title:'Changed',estimate:null,dueDate:null,assigneeId:null});
  assert.equal(result.status,200);assert.equal(result.data.issue.description,'Keep');assert.equal(result.data.issue.estimate,null);assert.equal(result.data.issue.dueDate,null);assert.equal(result.data.issue.assignee,null);
}));
test('issue list combines filters and uses opaque cursor pages',()=>scenario(async({request,project,create})=>{
  await create({title:'First',priority:1});await create({title:'Second',priority:2});await create({title:'Third',priority:2});
  const first=(await request('GET','/projects/'+project.id+'/issues?priority=2&limit=1')).data;
  assert.equal(first.items[0].title,'Third');assert.ok(first.nextCursor);
  const second=(await request('GET','/projects/'+project.id+'/issues?priority=2&limit=1&cursor='+first.nextCursor)).data;
  assert.equal(second.items[0].title,'Second');assert.equal(second.nextCursor,null);
  assert.equal((await request('GET','/projects/'+project.id+'/issues?q=FIRST')).data.items[0].title,'First');
}));
test('labels are project unique and propagate updates to issue snapshots',()=>scenario(async({server,request,project,create})=>{
  const label=(await request('POST','/projects/'+project.id+'/labels',{name:'Bug'})).data.label;
  assert.equal((await request('POST','/projects/'+project.id+'/labels',{name:'bug'})).status,409);
  const issue=(await create({title:'Fix',labelIds:[label.id]})).data.issue;
  const events=[];server.ctx.bus.subscribe(event=>events.push(event));
  assert.equal((await request('PATCH','/labels/'+label.id,{name:'Defect',color:'#ff0000'})).status,200);
  assert.equal((await request('GET','/issues/'+issue.id)).data.issue.labels[0].name,'Defect');
  assert.ok(events.some(event=>event.entityType==='issue'&&event.after.labels[0].name==='Defect'));
